# Documents and Spreadsheets post-install. Generated by tools/build.py from postinstall.template.ps1.
# Runs elevated (SYSTEM) after the App Updater installs the pinned LibreOffice MSI.
# Windows PowerShell 5.1. ASCII only. No network access.
# Steps 1 to 5 are critical (any failure exits 1). Step 6 (per-profile backups) only logs WARN.
$ErrorActionPreference = 'Stop'

# Policy values from package/settings.json: registry key below the policy root, value, type, final.
$PoliciesJson = @'
[
{"key": "org.openoffice.Office.Jobs\\Jobs\\org.openoffice.Office.Jobs:Job['UpdateCheck']\\Arguments\\AutoCheckEnabled", "value": "false", "type": "xs:boolean", "final": true},
{"key": "org.openoffice.Office.Update\\Update\\Enabled", "value": "false", "type": "xs:boolean", "final": true},
{"key": "org.openoffice.Office.Common\\Misc\\CrashReport", "value": "false", "type": "xs:boolean", "final": true},
{"key": "org.openoffice.Office.Common\\Misc\\ShowTipOfTheDay", "value": "false", "type": "xs:boolean", "final": true},
{"key": "org.openoffice.Office.UI.Infobar\\Enabled\\WhatsNew", "value": "false", "type": "xs:boolean", "final": true},
{"key": "org.openoffice.Office.UI.Infobar\\Enabled\\Donate", "value": "false", "type": "xs:boolean", "final": true},
{"key": "org.openoffice.Office.UI.Infobar\\Enabled\\GetInvolved", "value": "false", "type": "xs:boolean", "final": true},
{"key": "org.openoffice.Office.Common\\Security\\Scripting\\MacroSecurityLevel", "value": "2", "type": "xs:int", "final": true},
{"key": "org.openoffice.Setup\\Office\\Factories\\org.openoffice.Setup:Factory['com.sun.star.text.TextDocument']\\ooSetupFactoryDefaultFilter", "value": "MS Word 2007 XML", "type": "xs:string", "final": false},
{"key": "org.openoffice.Setup\\Office\\Factories\\org.openoffice.Setup:Factory['com.sun.star.sheet.SpreadsheetDocument']\\ooSetupFactoryDefaultFilter", "value": "Calc MS Excel 2007 XML", "type": "xs:string", "final": false},
{"key": "org.openoffice.Office.Common\\Save\\Document\\WarnAlienFormat", "value": "false", "type": "xs:boolean", "final": false},
{"key": "org.openoffice.Office.Recovery\\AutoSave\\Enabled", "value": "true", "type": "xs:boolean", "final": false},
{"key": "org.openoffice.Office.Recovery\\AutoSave\\TimeIntervall", "value": "5", "type": "xs:int", "final": false},
{"key": "org.openoffice.Office.Common\\Save\\Document\\CreateBackup", "value": "true", "type": "xs:boolean", "final": false},
{"key": "org.openoffice.Office.Writer\\AutoFunction\\Completion\\Enable", "value": "false", "type": "xs:boolean", "final": false},
{"key": "org.openoffice.Office.Common\\Misc\\SymbolSet", "value": "1", "type": "xs:short", "final": false},
{"key": "org.openoffice.Office.Paths\\Paths\\org.openoffice.Office.Paths:NamedPath['Work']\\WritePath", "value": "$(work)", "type": "xs:string", "final": false}
]
'@

# Policy keys written by earlier kit versions and no longer wanted, one per line (below the policy root).
$ObsoletePolicyKeys = @'

'@

# UI overlay files: "<module>/<menubar|toolbar>/<file>.xml <base64>", one per line.
$UiFiles = @'
scalc/menubar/menubar.xml 
scalc/toolbar/formatobjectbar.xml 
scalc/toolbar/standardbar.xml 
swriter/menubar/menubar.xml 
swriter/toolbar/standardbar.xml 
swriter/toolbar/textobjectbar.xml 
'@

# The shared extension (senior-suite.oxt), base64.
$OxtB64 = @'

'@

# Launcher icons: "<name>.ico <base64>", one per line.
$IconFiles = @'
documents.ico 
spreadsheets.ico 
'@

$PolicyRoot = 'SOFTWARE\Policies\LibreOffice'
$ExtensionId = 'org.example.seniorsuite'

$logDir = Join-Path $env:ProgramData 'AppUpdater'
$logFile = Join-Path $logDir 'postinstall-office-suite.log'

function Write-Log {
    param([string]$Message)
    $stamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    Add-Content -LiteralPath $logFile -Value ("{0} {1}" -f $stamp, $Message) -Encoding ASCII
}

function Test-Reparse {
    # True when the path exists and is a reparse point (junction or symlink).
    param([string]$Path)
    $i = Get-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
    return [bool]($i -and ($i.Attributes -band [IO.FileAttributes]::ReparsePoint))
}

function Hide-ProfilePath {
    # Exception messages can contain full paths. Replace "<SystemDrive>\Users\<name>" with
    # "<profile>" so the log never holds more than the leaf names logged on purpose.
    param([string]$Message)
    $users = Join-Path $env:SystemDrive 'Users'
    # the name ends at the next backslash or quote (names may contain spaces)
    $pattern = [regex]::Escape($users + '\') + '[^\\''"]+'
    return [regex]::Replace([string]$Message, $pattern, '<profile>', [Text.RegularExpressions.RegexOptions]::IgnoreCase)
}

function Get-LibreOfficeDir {
    # Always read the 64-bit registry view, even from a 32-bit host process.
    $paths = @(
        'SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
        'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'
    )
    $base = [Microsoft.Win32.RegistryKey]::OpenBaseKey('LocalMachine', 'Registry64')
    foreach ($p in $paths) {
        $key = $base.OpenSubKey($p)
        if (-not $key) { continue }
        foreach ($name in $key.GetSubKeyNames()) {
            $sub = $key.OpenSubKey($name)
            if (-not $sub) { continue }
            $dn = $sub.GetValue('DisplayName')
            $loc = $sub.GetValue('InstallLocation')
            if ($dn -and ([string]$dn).StartsWith('LibreOffice') -and $loc) {
                $loc = ([string]$loc).Trim().Trim('"').TrimEnd('\')
                if ($loc -and (Test-Path -LiteralPath (Join-Path $loc 'program\soffice.exe'))) {
                    return $loc
                }
            }
        }
    }
    $pf = $env:ProgramW6432
    if (-not $pf) { $pf = $env:ProgramFiles }
    $fallback = Join-Path $pf 'LibreOffice'
    if (Test-Path -LiteralPath (Join-Path $fallback 'program\soffice.exe')) {
        return $fallback
    }
    throw 'soffice.exe not found (registry InstallLocation or ProgramW6432 fallback)'
}

function New-SafeDir {
    # Create a folder (if needed) that is not a reparse point. Checked before and after
    # creating it, so a junction planted meanwhile can never redirect a write.
    param([string]$Path)
    if (Test-Reparse $Path) { throw ("reparse point: {0}" -f (Split-Path -Leaf $Path)) }
    if (-not (Test-Path -LiteralPath $Path -PathType Container)) {
        New-Item -ItemType Directory -Path $Path -Force | Out-Null
    }
    if (Test-Reparse $Path) { throw ("reparse point: {0}" -f (Split-Path -Leaf $Path)) }
}

function Get-OwnerProblem {
    # Read-only. $null when the item is owned by SYSTEM or Administrators, else a short reason.
    param([string]$Path)
    $owner = (Get-Acl -LiteralPath $Path).GetOwner([Security.Principal.SecurityIdentifier]).Value
    if ($owner -ne 'S-1-5-18' -and $owner -ne 'S-1-5-32-544') { return ("owner is {0}" -f $owner) }
    return $null
}

# Rights that let a holder change what is in a folder: write/create files (0x2), append/create
# folders (0x4), write extended attributes (0x10), delete children (0x40), write attributes
# (0x100), delete (0x10000), change permissions (0x40000), take ownership (0x80000),
# generic all (0x10000000) and generic write (0x40000000).
$WriteMask = 0x500D0156

function Get-AclProblem {
    # Read-only (no ACL changes). Returns $null when the folder is admin-only: not a reparse
    # point, owned by SYSTEM or Administrators, access rules protected from inheritance, and
    # no Allow rule giving any write right to another SID. Otherwise a short reason.
    param([string]$Path)
    if (Test-Reparse $Path) { return 'it is a reparse point' }
    $ownerProblem = Get-OwnerProblem $Path
    if ($ownerProblem) { return $ownerProblem }
    $acl = Get-Acl -LiteralPath $Path
    if (-not $acl.AreAccessRulesProtected) { return 'its access rules are inherited (not protected)' }
    foreach ($r in $acl.GetAccessRules($true, $true, [Security.Principal.SecurityIdentifier])) {
        if ($r.AccessControlType -ne [Security.AccessControl.AccessControlType]::Allow) { continue }
        $sid = $r.IdentityReference.Value
        if ($sid -eq 'S-1-5-18' -or $sid -eq 'S-1-5-32-544') { continue }
        if (([long]$r.FileSystemRights -band [long]$WriteMask) -ne 0) {
            return ("{0} has write access" -f $sid)
        }
    }
    return $null
}

function Assert-AdminOwned {
    # Read-only check (no ACL changes): the folder's owner must be SYSTEM or Administrators.
    # A folder that a standard user created first is owned by that user, who could then swap
    # files in it between our write and their use.
    param([string]$Path)
    $sid = (Get-Acl -LiteralPath $Path).GetOwner([Security.Principal.SecurityIdentifier]).Value
    if ($sid -ne 'S-1-5-18' -and $sid -ne 'S-1-5-32-544') {
        throw ("untrusted owner {0}: {1}" -f $sid, (Split-Path -Leaf $Path))
    }
}

function Invoke-Unopkg {
    # Run unopkg.com and return its exit code. Its stderr must not become a terminating
    # error (Windows PowerShell 5.1 wraps native stderr as error records).
    param([string[]]$Arguments)
    $prev = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        & $unopkg @Arguments $envArg 2>&1 | Out-Null
        return $LASTEXITCODE
    }
    finally {
        $ErrorActionPreference = $prev
    }
}

function Split-Embedded {
    # "<name> <base64>" lines -> list of @(name, bytes).
    param([string]$Text)
    $out = @()
    foreach ($line in ($Text -split "`r?`n")) {
        if (-not $line) { continue }
        $i = $line.IndexOf(' ')
        $out += ,@($line.Substring(0, $i), [Convert]::FromBase64String($line.Substring($i + 1)))
    }
    return ,$out
}

# 0. The App Updater's folder (default DataDir) must already exist and be admin-only: the log
# goes there and the extension for every user is installed from its cache. This runs before
# anything is logged, so a failure goes to stdout only (writing into an unsafe folder is not safe).
$problem = $null
try {
    if (-not (Test-Path -LiteralPath $logDir -PathType Container)) {
        $problem = 'folder does not exist; the App Updater creates it admin-only (manual install: see TECHNICIAN.md)'
    }
    else {
        $problem = Get-AclProblem $logDir
    }
    # An existing log file must not be a link and must be admin-owned before we append to it.
    if (-not $problem -and (Test-Path -LiteralPath $logFile)) {
        if (Test-Reparse $logFile) {
            $problem = 'the log file is a reparse point'
        }
        else {
            $lp = Get-OwnerProblem $logFile
            if ($lp) { $problem = 'log file ' + $lp }
        }
    }
}
catch {
    $problem = (Hide-ProfilePath $_.Exception.Message)
}
if ($problem) {
    Write-Output ("ERROR %ProgramData%\AppUpdater is not safe to use: {0}" -f $problem)
    exit 1
}

$exitCode = 0
try {
    Write-Log 'postinstall start'

    # 1. Locate the install dir.
    $installDir = Get-LibreOfficeDir
    Write-Log ("install dir: {0}" -f (Split-Path -Leaf $installDir))

    # 2. Machine policies, in the 64-bit view of HKLM\SOFTWARE\Policies\LibreOffice. First the
    # keys earlier kit versions wrote and this one dropped are deleted. Locked settings carry
    # Final=1; a setting that is no longer locked loses its Final value.
    $hklm = [Microsoft.Win32.RegistryKey]::OpenBaseKey('LocalMachine', 'Registry64')
    foreach ($key in ($ObsoletePolicyKeys -split "`r?`n")) {
        if (-not $key) { continue }
        if ($key.Contains('..') -or $key.StartsWith('\')) { throw ("bad obsolete policy key {0}" -f $key) }
        $hklm.DeleteSubKeyTree($PolicyRoot + '\' + $key, $false)
        Write-Log ("removed obsolete policy {0}" -f $key)
    }
    $count = 0
    foreach ($p in ($PoliciesJson | ConvertFrom-Json)) {
        $k = $hklm.CreateSubKey($PolicyRoot + '\' + [string]$p.key)
        if (-not $k) { throw ("cannot create policy key {0}" -f [string]$p.key) }
        $k.SetValue('Value', [string]$p.value, [Microsoft.Win32.RegistryValueKind]::String)
        $k.SetValue('Type', [string]$p.type, [Microsoft.Win32.RegistryValueKind]::String)
        if ($p.final) {
            $k.SetValue('Final', 1, [Microsoft.Win32.RegistryValueKind]::DWord)
        }
        else {
            $k.DeleteValue('Final', $false)
        }
        $k.Close()
        $count++
    }
    Write-Log ("policies written: {0}" -f $count)

    # 3. UI overlay (menubar and toolbars) into the shared soffice.cfg. Every MSI install or
    # repair restores the upstream files, so this runs every time.
    $modulesDir = Join-Path $installDir 'share\config\soffice.cfg\modules'
    foreach ($e in (Split-Embedded $UiFiles)) {
        $rel = $e[0]
        if ($rel -notmatch '^(swriter|scalc)/(menubar|toolbar)/[A-Za-z0-9_.-]+\.xml$') {
            throw ("bad overlay path {0}" -f $rel)
        }
        $target = Join-Path $modulesDir ($rel.Replace('/', '\'))
        $parent = Split-Path -Parent $target
        if (-not (Test-Path -LiteralPath $parent -PathType Container)) {
            New-Item -ItemType Directory -Path $parent -Force | Out-Null
        }
        [IO.File]::WriteAllBytes($target, $e[1])
        Write-Log ("wrote overlay {0}" -f $rel)
    }

    # 4. Shared extension, installed for every user. The cache lives in the App Updater's
    # admin-only folder; both folders must be admin-owned, and the .oxt is created fresh.
    # unopkg runs with its own user installation there instead of SYSTEM's profile.
    $cacheDir = Join-Path $env:ProgramData 'AppUpdater\cache'
    New-SafeDir $cacheDir
    Assert-AdminOwned $cacheDir
    $oxtPath = Join-Path $cacheDir 'senior-suite.oxt'
    if (Test-Path -LiteralPath $oxtPath) { Remove-Item -LiteralPath $oxtPath -Force }
    $oxtBytes = [Convert]::FromBase64String($OxtB64)
    $fs = [IO.File]::Open($oxtPath, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
    try { $fs.Write($oxtBytes, 0, $oxtBytes.Length) } finally { $fs.Close() }
    Write-Log ("wrote {0}" -f (Split-Path -Leaf $oxtPath))
    $profileDir = Join-Path $cacheDir 'unopkg-profile'
    New-SafeDir $profileDir
    Assert-AdminOwned $profileDir
    $unopkg = Join-Path $installDir 'program\unopkg.com'
    $envArg = '-env:UserInstallation=' + ([Uri]$profileDir).AbsoluteUri
    # Removing first makes a reinstall of the same version work; it fails when the
    # extension is not installed yet, so its exit code is only logged.
    $rc = Invoke-Unopkg @('remove', '--shared', 'org.example.seniorsuite')
    Write-Log ("unopkg remove exit {0}" -f $rc)
    $rc = Invoke-Unopkg @('add', '--shared', '--suppress-license', '--force', $oxtPath)
    if ($rc -ne 0) { throw ("unopkg add failed with exit code {0}" -f $rc) }
    Write-Log ("unopkg add {0}: ok" -f $ExtensionId)

    # 5. Launchers: our icons, "Documents" and "Spreadsheets" in the all-users Start menu and
    # on the Public Desktop, and the MSI's LibreOffice entries moved into a Tools subfolder.
    $suiteDir = Join-Path $env:ProgramData 'SeniorSuite'
    $iconDir = Join-Path $env:ProgramData 'SeniorSuite\icons'
    New-SafeDir $suiteDir
    New-SafeDir $iconDir
    Assert-AdminOwned $suiteDir
    Assert-AdminOwned $iconDir
    foreach ($e in (Split-Embedded $IconFiles)) {
        if ($e[0] -notmatch '^[a-z]+\.ico$') { throw ("bad icon name {0}" -f $e[0]) }
        [IO.File]::WriteAllBytes((Join-Path $iconDir $e[0]), $e[1])
        Write-Log ("wrote icon {0}" -f $e[0])
    }
    $soffice = Join-Path $installDir 'program\soffice.exe'
    $menuDir = [Environment]::GetFolderPath('CommonPrograms')
    $deskDir = [Environment]::GetFolderPath('CommonDesktopDirectory')
    if (-not $menuDir) { throw 'all-users Start menu folder not found' }
    if (-not $deskDir) { throw 'Public Desktop folder not found' }
    $launchers = @(
        @('Documents', '--writer --nologo', 'documents.ico'),
        @('Spreadsheets', '--calc --nologo', 'spreadsheets.ico')
    )
    $shell = New-Object -ComObject WScript.Shell
    foreach ($l in $launchers) {
        foreach ($where in @($menuDir, $deskDir)) {
            $lnkPath = Join-Path $where ($l[0] + '.lnk')
            $lnk = $shell.CreateShortcut($lnkPath)
            $lnk.TargetPath = $soffice
            $lnk.Arguments = $l[1]
            $lnk.WorkingDirectory = Split-Path -Parent $soffice
            $lnk.IconLocation = (Join-Path $iconDir $l[2]) + ',0'
            $lnk.Description = $l[0]
            $lnk.Save()
            Write-Log ("wrote {0} in {1}" -f (Split-Path -Leaf $lnkPath), (Split-Path -Leaf $where))
        }
    }
    # The MSI puts its shortcuts in Programs\LibreOffice. They are moved, not deleted, so
    # repair and Troubleshoot Mode stay reachable; a reinstall puts them back and this moves them again.
    $toolsDir = Join-Path $menuDir 'Tools'
    $msiMenu = Join-Path $menuDir 'LibreOffice'
    foreach ($src in @($msiMenu, $menuDir)) {
        if (-not (Test-Path -LiteralPath $src -PathType Container)) { continue }
        if (Test-Reparse $src) { throw ("reparse point: {0}" -f (Split-Path -Leaf $src)) }
        foreach ($f in [IO.Directory]::GetFiles($src, 'LibreOffice*.lnk')) {
            New-SafeDir $toolsDir
            $dest = Join-Path $toolsDir (Split-Path -Leaf $f)
            if (Test-Path -LiteralPath $dest) { Remove-Item -LiteralPath $dest -Force }
            Move-Item -LiteralPath $f -Destination $dest
            Write-Log ("moved {0} to Tools" -f (Split-Path -Leaf $f))
        }
    }
    if ((Test-Path -LiteralPath $msiMenu -PathType Container) -and -not (Test-Reparse $msiMenu)) {
        if ([IO.Directory]::GetFileSystemEntries($msiMenu).Length -eq 0) {
            [IO.Directory]::Delete($msiMenu)
            Write-Log 'removed empty LibreOffice Start menu folder'
        }
    }

    # 6. Existing profiles: a user's own menubar/toolbar folders override ours, so rename them
    # to a dated backup. Non-critical: failures are logged as WARN and do not change the exit
    # code. Renames run as SYSTEM inside user-owned folders, so no level of the path may be a
    # reparse point (a rename must never go through a junction).
    $stamp = Get-Date -Format 'yyyyMMdd'
    $profiles = @()
    $cands = @()
    try {
        $plist = $hklm.OpenSubKey('SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList')
        if (-not $plist) { throw 'ProfileList key not found' }
        foreach ($sid in $plist.GetSubKeyNames()) {
            try {
                # Skip the built-in service accounts (SYSTEM, LocalService, NetworkService).
                if ($sid -eq 'S-1-5-18' -or $sid -eq 'S-1-5-19' -or $sid -eq 'S-1-5-20') { continue }
                $sk = $plist.OpenSubKey($sid)
                if (-not $sk) { continue }
                $pp = $sk.GetValue('ProfileImagePath')
                if ($pp) {
                    $pp = [Environment]::ExpandEnvironmentVariables([string]$pp)
                    $cands += ,@((Split-Path -Leaf $pp), $pp)
                }
            }
            catch {
                try { Write-Log ("WARN backup enumerate {0}: {1}" -f $sid, (Hide-ProfilePath $_.Exception.Message)) } catch { }
            }
        }
    }
    catch {
        try { Write-Log ("WARN backup enumerate profiles: {0}" -f (Hide-ProfilePath $_.Exception.Message)) } catch { }
    }
    $found = @{}
    foreach ($c in $cands) {
        try {
            $path = $c[1]
            $key = $path.ToLowerInvariant()
            if ($found.ContainsKey($key)) { continue }
            $found[$key] = $true
            if (-not (Test-Path -LiteralPath $path -PathType Container)) { continue }
            if (Test-Reparse $path) {
                Write-Log ("WARN skip reparse point (profile): {0}" -f (Split-Path -Leaf $path))
                continue
            }
            $profiles += New-Object psobject -Property @{ Name = $c[0]; FullName = $path }
        }
        catch {
            try { Write-Log ("WARN backup enumerate {0}: {1}" -f $c[0], (Hide-ProfilePath $_.Exception.Message)) } catch { }
        }
    }
    $chain = @('AppData', 'Roaming', 'LibreOffice', '4', 'user', 'config', 'soffice.cfg', 'modules')
    foreach ($prof in $profiles) {
        try {
            $cur = $prof.FullName
            $ok = $true
            foreach ($part in $chain) {
                $cur = Join-Path $cur $part
                if (-not (Test-Path -LiteralPath $cur -PathType Container)) { $ok = $false; break }
                if (Test-Reparse $cur) {
                    Write-Log ("WARN skip reparse point ({0}): {1}" -f $part, $prof.Name)
                    $ok = $false
                    break
                }
            }
            if (-not $ok) { continue }
            foreach ($module in @('swriter', 'scalc')) {
                $modDir = Join-Path $cur $module
                if (-not (Test-Path -LiteralPath $modDir -PathType Container)) { continue }
                if (Test-Reparse $modDir) {
                    Write-Log ("WARN skip reparse point ({0}): {1}" -f $module, $prof.Name)
                    continue
                }
                foreach ($kind in @('menubar', 'toolbar')) {
                    $dir = Join-Path $modDir $kind
                    if (-not (Test-Path -LiteralPath $dir -PathType Container)) { continue }
                    if (Test-Reparse $dir) {
                        Write-Log ("WARN skip reparse point ({0}\{1}): {2}" -f $module, $kind, $prof.Name)
                        continue
                    }
                    $new = $kind + '.backup-' + $stamp
                    $n = 2
                    while (Test-Path -LiteralPath (Join-Path $modDir $new)) {
                        $new = $kind + '.backup-' + $stamp + '-' + $n
                        $n++
                    }
                    # Re-check the parent right before the rename.
                    if (Test-Reparse $modDir) {
                        Write-Log ("WARN skip reparse point ({0}): {1}" -f $module, $prof.Name)
                        break
                    }
                    [IO.Directory]::Move($dir, (Join-Path $modDir $new))
                    Write-Log ("backed up {0}\{1} as {2}: {3}" -f $module, $kind, $new, $prof.Name)
                }
            }
        }
        catch {
            try { Write-Log ("WARN backup {0}: {1}" -f $prof.Name, (Hide-ProfilePath $_.Exception.Message)) } catch { }
        }
    }

    Write-Log 'postinstall done'
}
catch {
    $exitCode = 1
    try { Write-Log ("ERROR line {0}: {1}" -f $_.InvocationInfo.ScriptLineNumber, (Hide-ProfilePath $_.Exception.Message)) } catch { }
}
exit $exitCode
